namespace Domain.Entities;

using Domain.Common;
using Domain.Enums;

public sealed class Registration : BaseEntity
{
    // Generated by the server, format CS27-0001
    public string RegistrationNumber { get; set; } = default!;

    // Set by the server in UTC
    public DateTime RegistrationDate { get; set; }

    public string ParticipantName { get; set; } = default!;
    public string ContactNumber { get; set; } = default!;
    public string Email { get; set; } = default!;
    public string Address { get; set; } = default!;
    public string CarMakeModel { get; set; } = default!;
    public string PlateNumber { get; set; } = default!;

    public RegistrationType RegistrationType { get; set; }

    // Default is Pending
    public RegistrationStatus Status { get; set; } = RegistrationStatus.Pending;

    // Set by the server from the registration type
    public decimal RegistrationFee { get; set; }

    public decimal AmountPaid { get; set; }

    // Business rule: the fee depends only on the registration type
    public static decimal GetFeeFor(RegistrationType registrationType) => registrationType switch
    {
        RegistrationType.Exhibitor => 1500m,
        RegistrationType.Competitor => 2500m,
        RegistrationType.VIP => 5000m,
        _ => throw new ArgumentOutOfRangeException(
            nameof(registrationType), registrationType, "Unknown registration type.")
    };

    // Business rule: payment status is computed, never stored
    public PaymentStatus GetPaymentStatus()
    {
        if (AmountPaid <= 0)
        {
            return PaymentStatus.Unpaid;
        }

        if (AmountPaid >= RegistrationFee)
        {
            return PaymentStatus.Paid;
        }

        return PaymentStatus.Partial;
    }
}
